//! Sound effects and music. Sounds live in `assets/sounds/` and are
//! generated by `tools/make_sounds.py`; a file of the same name replaces one.

use bevy::audio::Volume;
use bevy::prelude::*;

use crate::data::asset_exists;
use crate::day_cycle::{Phase, Progress};
use crate::fx::{Cue, Voice};
use crate::rng::Rng;
use crate::save::Settings;
use crate::title::Opening;

const MUSIC_FADE_SECS: f32 = 2.0;
/// Seasons with music of their own: `evening_music_<name>.ogg` and
/// `night_ambience_<name>.ogg`. Every other season, or a missing file, plays
/// the first season's tracks.
const SEASON_MUSIC: &[(u32, &str)] = &[(2, "winter"), (3, "spring")];
/// Seconds between two ghost "wooos" or hums, so several ghosts never
/// turn into a choir. Whispers and startled sounds always play.
const VOICE_GAP_SECS: f32 = 2.5;
/// A cue that still has no audio sink after this delay is no longer timely.
const MAX_CUE_DELAY: f32 = 2.0;

pub struct SoundPlugin;

impl Plugin for SoundPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<Sounds>()
            .init_resource::<CurrentMusic>()
            .add_systems(
                Update,
                (play_cues, update_effects, choose_music, fade_music),
            );
    }
}

#[derive(Component)]
struct Effect {
    gain: f32,
    queued_at: f32,
}

#[derive(Resource)]
pub struct Sounds {
    bell: Handle<AudioSource>,
    coins: Handle<AudioSource>,
    chime: Handle<AudioSource>,
    midnight: Handle<AudioSource>,
    crash: Handle<AudioSource>,
    click: Handle<AudioSource>,
    sigh: Handle<AudioSource>,
    ghost_whoo: [Handle<AudioSource>; 3],
    ghost_whisper: Handle<AudioSource>,
    ghost_hum: Handle<AudioSource>,
    ghost_flee: Handle<AudioSource>,
    evening_music: Handle<AudioSource>,
    night_ambience: Handle<AudioSource>,
}

impl FromWorld for Sounds {
    fn from_world(world: &mut World) -> Self {
        let assets = world.resource::<AssetServer>();
        Self {
            bell: assets.load("sounds/bell.ogg"),
            coins: assets.load("sounds/coins.ogg"),
            chime: assets.load("sounds/chime.ogg"),
            midnight: assets.load("sounds/midnight.ogg"),
            crash: assets.load("sounds/crash.ogg"),
            click: assets.load("sounds/click.ogg"),
            sigh: assets.load("sounds/sigh.ogg"),
            ghost_whoo: [1, 2, 3].map(|n| assets.load(format!("sounds/ghost_whoo_{n}.ogg"))),
            ghost_whisper: assets.load("sounds/ghost_whisper.ogg"),
            ghost_hum: assets.load("sounds/ghost_hum.ogg"),
            ghost_flee: assets.load("sounds/ghost_flee.ogg"),
            evening_music: assets.load("sounds/evening_music.ogg"),
            night_ambience: assets.load("sounds/night_ambience.ogg"),
        }
    }
}

fn play_cues(
    mut commands: Commands,
    mut cues: MessageReader<Cue>,
    sounds: Res<Sounds>,
    settings: Res<Settings>,
    time: Res<Time<Real>>,
    mut rng: ResMut<Rng>,
    mut last_voice: Local<Option<f32>>,
) {
    for cue in cues.read() {
        if !settings.sound || settings.effects == 0.0 {
            continue;
        }
        if let Cue::GhostVoice(voice, pitch) = *cue {
            let now = time.elapsed_secs();
            let ambient = matches!(voice, Voice::Whoo | Voice::Hum);
            if ambient && last_voice.is_some_and(|t| now - t < VOICE_GAP_SECS) {
                continue;
            }
            *last_voice = Some(now);
            let (sound, volume) = match voice {
                Voice::Whoo => (&sounds.ghost_whoo[rng.index(3)], 0.45),
                Voice::Whisper => (&sounds.ghost_whisper, 0.55),
                Voice::Hum => (&sounds.ghost_hum, 0.4),
                Voice::Flee => (&sounds.ghost_flee, 0.45),
            };
            commands.spawn((
                Effect {
                    gain: volume,
                    queued_at: now,
                },
                AudioPlayer::new(sound.clone()),
                PlaybackSettings {
                    volume: Volume::Linear(volume * settings.effects),
                    speed: pitch * rng.range(0.96, 1.04),
                    ..PlaybackSettings::DESPAWN
                },
            ));
            continue;
        }
        let (sound, volume, vary) = match cue {
            Cue::GhostEnters => (&sounds.bell, 0.5, false),
            Cue::Paid | Cue::ChangeGiven | Cue::Tip(..) => (&sounds.coins, 0.7, true),
            Cue::Ascend(_) => (&sounds.chime, 0.7, false),
            Cue::Knock(_) => (&sounds.crash, 0.6, true),
            Cue::Disappointed => (&sounds.sigh, 0.6, false),
            Cue::Click => (&sounds.click, 0.5, true),
            Cue::Midnight => (&sounds.midnight, 0.8, false),
            Cue::GhostVoice(..) => continue,
        };
        // A little pitch variation keeps repeated sounds from feeling canned.
        let speed = if vary { rng.range(0.93, 1.07) } else { 1.0 };
        commands.spawn((
            Effect {
                gain: volume,
                queued_at: time.elapsed_secs(),
            },
            AudioPlayer::new(sound.clone()),
            PlaybackSettings {
                volume: Volume::Linear(volume * settings.effects),
                speed,
                ..PlaybackSettings::DESPAWN
            },
        ));
    }
}

fn update_effects(
    mut commands: Commands,
    settings: Res<Settings>,
    time: Res<Time<Real>>,
    mut playing: Query<(Entity, &Effect, Option<&mut AudioSink>)>,
) {
    for (entity, effect, sink) in &mut playing {
        if !settings.sound || settings.effects == 0.0 {
            commands.entity(entity).despawn();
        } else if let Some(mut sink) = sink {
            if settings.is_changed() || sink.is_added() {
                sink.set_volume(Volume::Linear(effect.gain * settings.effects));
            }
        } else if time.elapsed_secs() - effect.queued_at >= MAX_CUE_DELAY {
            // Without an output device Bevy never starts or cleans up this player.
            commands.entity(entity).despawn();
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Track {
    Evening(u32),
    Night(u32),
}

impl Track {
    /// The file to play: the season's own, if there is one.
    fn path(self) -> String {
        let (base, season) = match self {
            Track::Evening(s) => ("evening_music", s),
            Track::Night(s) => ("night_ambience", s),
        };
        SEASON_MUSIC
            .iter()
            .find(|(n, _)| *n == season)
            .map(|(_, name)| format!("sounds/{base}_{name}.ogg"))
            .filter(|p| asset_exists(p))
            .unwrap_or_else(|| format!("sounds/{base}.ogg"))
    }
}

#[derive(Resource, Default)]
struct CurrentMusic(Option<Track>);

/// A playing music track and where its volume is heading.
#[derive(Component)]
struct Music {
    volume: f32,
    target: f32,
}

fn choose_music(
    mut commands: Commands,
    phase: Res<State<Phase>>,
    settings: Res<Settings>,
    sounds: Res<Sounds>,
    asset_server: Res<AssetServer>,
    progress: Res<Progress>,
    opening: Option<Res<Opening>>,
    mut current: ResMut<CurrentMusic>,
    mut playing: Query<&mut Music>,
) {
    // The title screen keeps the first season's tune.
    let season = if *phase.get() == Phase::Menu {
        1
    } else {
        progress.season
    };
    let wanted = (settings.sound && opening.is_none()).then(|| match phase.get() {
        Phase::Night => Track::Night(season),
        _ => Track::Evening(season),
    });
    if wanted == current.0 {
        return;
    }
    current.0 = wanted;
    for mut music in &mut playing {
        music.target = 0.0;
    }
    let Some(track) = wanted else { return };
    let path = track.path();
    let (handle, target) = match track {
        Track::Evening(_) if path == "sounds/evening_music.ogg" => {
            (sounds.evening_music.clone(), 0.6)
        }
        Track::Night(_) if path == "sounds/night_ambience.ogg" => {
            (sounds.night_ambience.clone(), 0.8)
        }
        Track::Evening(_) => (asset_server.load(path), 0.6),
        Track::Night(_) => (asset_server.load(path), 0.8),
    };
    commands.spawn((
        AudioPlayer::new(handle),
        PlaybackSettings {
            volume: Volume::SILENT,
            ..PlaybackSettings::LOOP
        },
        Music {
            volume: 0.0,
            target,
        },
    ));
}

/// Fades music in and out on real time, so it also works while paused.
fn fade_music(
    mut commands: Commands,
    time: Res<Time<Real>>,
    settings: Res<Settings>,
    mut playing: Query<(Entity, &mut Music, Option<&mut AudioSink>)>,
) {
    let step = time.delta_secs() / MUSIC_FADE_SECS;
    for (entity, mut music, sink) in &mut playing {
        let diff = music.target - music.volume;
        music.volume += diff.clamp(-step, step);
        if !settings.sound || (music.target == 0.0 && music.volume <= 0.0) {
            commands.entity(entity).despawn();
        } else if let Some(mut sink) = sink {
            sink.set_volume(Volume::Linear(music.volume * settings.music));
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cues_without_an_audio_sink_expire() {
        let mut app = App::new();
        app.init_resource::<Settings>()
            .init_resource::<Time<Real>>()
            .add_systems(Update, update_effects);
        let cue = app
            .world_mut()
            .spawn(Effect {
                gain: 0.5,
                queued_at: 0.0,
            })
            .id();
        app.update();
        assert!(app.world().get_entity(cue).is_ok());
        app.world_mut()
            .resource_mut::<Time<Real>>()
            .advance_by(std::time::Duration::from_secs_f32(MAX_CUE_DELAY));
        app.update();
        assert!(app.world().get_entity(cue).is_err());
    }

    #[test]
    fn seasons_play_their_own_music() {
        assert_eq!(Track::Evening(1).path(), "sounds/evening_music.ogg");
        assert_eq!(Track::Evening(2).path(), "sounds/evening_music_winter.ogg");
        assert_eq!(Track::Night(3).path(), "sounds/night_ambience_spring.ogg");
        // A season without its own music keeps the first season's.
        assert_eq!(Track::Night(9).path(), "sounds/night_ambience.ogg");
    }
}
